diff --git a/sql/persisted_variable.cc b/sql/persisted_variable.cc
index b12e50123793..b9fb8f317c13 100644
--- a/sql/persisted_variable.cc
+++ b/sql/persisted_variable.cc
@@ -1108,6 +1108,10 @@ bool Persisted_variables_cache::reset_persisted_variables(THD *thd,
   auto it_ro = m_persist_ro_variables.find(var_name);

   if (reset_all) {
+    /* check for necessary privileges */
+    if (!m_persist_variables.empty() && check_priv(thd, false)) goto end;
+    if (!m_persist_ro_variables.empty() && check_priv(thd, true)) goto end;
+
     if (!m_persist_variables.empty()) {
       m_persist_variables.clear();
       flush = 1;
@@ -1130,6 +1134,7 @@ bool Persisted_variables_cache::reset_persisted_variables(THD *thd,
                              m_persist_variables.end(), checkvariable);
       if (it != m_persist_variables.end()) {
         /* if variable is present in config file remove it */
+        if (check_priv(thd, false)) goto end;
         m_persist_variables.erase(it);
         flush = 1;
         not_present = 0;
@@ -1139,12 +1144,14 @@ bool Persisted_variables_cache::reset_persisted_variables(THD *thd,
       auto it = std::find_if(m_persist_plugin_variables.begin(),
                              m_persist_plugin_variables.end(), checkvariable);
       if (it != m_persist_plugin_variables.end()) {
+        if (check_priv(thd, false)) goto end;
         m_persist_plugin_variables.erase(it);
         flush = 1;
         not_present = 0;
       }
     }
     if (it_ro != m_persist_ro_variables.end()) {
+      if (check_priv(thd, true)) goto end;
       /* if static variable is present in config file remove it */
       m_persist_ro_variables.erase(it_ro);
       flush = 1;
@@ -1167,6 +1174,10 @@ bool Persisted_variables_cache::reset_persisted_variables(THD *thd,
   if (flush) flush_to_file();

   return result;
+
+end:
+  unlock();
+  return 1;
 }

 /**
diff --git a/sql/set_var.cc b/sql/set_var.cc
index 9e567498d125..200c19076db7 100644
--- a/sql/set_var.cc
+++ b/sql/set_var.cc
@@ -152,6 +152,44 @@ void sys_var_end() {
   DBUG_VOID_RETURN;
 }

+/**
+  This function will check for necessary privileges needed to perform RESET
+  PERSIST or SET PERSIST[_ONLY] operation.
+
+  @param [in] thd                     Pointer to connection handle.
+  @param [in] static_variable         describes if variable is static or dynamic
+
+  @return 0 Success
+  @return 1 Failure
+*/
+bool check_priv(THD *thd, bool static_variable) {
+  Security_context *sctx = thd->security_context();
+  /* for dynamic variables user needs SUPER_ACL or SYSTEM_VARIABLES_ADMIN */
+  if (!static_variable) {
+    if (!sctx->check_access(SUPER_ACL) &&
+        !(sctx->has_global_grant(STRING_WITH_LEN("SYSTEM_VARIABLES_ADMIN"))
+              .first)) {
+      my_error(ER_SPECIFIC_ACCESS_DENIED_ERROR, MYF(0),
+               "SUPER or SYSTEM_VARIABLES_ADMIN");
+      return 1;
+    }
+  } else {
+    /*
+     for static variables user needs both SYSTEM_VARIABLES_ADMIN and
+     PERSIST_RO_VARIABLES_ADMIN
+    */
+    if (!(sctx->has_global_grant(STRING_WITH_LEN("SYSTEM_VARIABLES_ADMIN"))
+              .first &&
+          sctx->has_global_grant(STRING_WITH_LEN("PERSIST_RO_VARIABLES_ADMIN"))
+              .first)) {
+      my_error(ER_PERSIST_ONLY_ACCESS_DENIED_ERROR, MYF(0),
+               "SYSTEM_VARIABLES_ADMIN and PERSIST_RO_VARIABLES_ADMIN");
+      return 1;
+    }
+  }
+  return 0;
+}
+
 /**
   sys_var constructor

@@ -872,29 +910,10 @@ int set_var::resolve(THD *thd) {
   }
   if (type == OPT_GLOBAL || type == OPT_PERSIST) {
     /* Either the user has SUPER_ACL or she has SYSTEM_VARIABLES_ADMIN */
-    Security_context *sctx = thd->security_context();
-    if (!sctx->check_access(SUPER_ACL) &&
-        !sctx->has_global_grant(STRING_WITH_LEN("SYSTEM_VARIABLES_ADMIN"))
-             .first) {
-      my_error(ER_SPECIFIC_ACCESS_DENIED_ERROR, MYF(0),
-               "SUPER or SYSTEM_VARIABLES_ADMIN");
-      DBUG_RETURN(1);
-    }
+    if (check_priv(thd, false)) DBUG_RETURN(1);
   }
   if (type == OPT_PERSIST_ONLY) {
-    Security_context *sctx = thd->security_context();
-    /*
-     user should have both SYSTEM_VARIABLES_ADMIN and
-     "PERSIST_RO_VARIABLES_ADMIN" privilege to persist read only variables
-    */
-    if (!(sctx->has_global_grant(STRING_WITH_LEN("SYSTEM_VARIABLES_ADMIN"))
-              .first &&
-          sctx->has_global_grant(STRING_WITH_LEN("PERSIST_RO_VARIABLES_ADMIN"))
-              .first)) {
-      my_error(ER_PERSIST_ONLY_ACCESS_DENIED_ERROR, MYF(0),
-               "SYSTEM_VARIABLES_ADMIN and PERSIST_RO_VARIABLES_ADMIN");
-      DBUG_RETURN(1);
-    }
+    if (check_priv(thd, true)) DBUG_RETURN(1);
   }
   /* value is a NULL pointer if we are using SET ... = DEFAULT */
   if (!value) DBUG_RETURN(0);
diff --git a/sql/set_var.h b/sql/set_var.h
index 95501665da09..cea7eb1f5048 100644
--- a/sql/set_var.h
+++ b/sql/set_var.h
@@ -506,4 +506,7 @@ int sys_var_init();
 int sys_var_add_options(std::vector<my_option> *long_options, int parse_flags);
 void sys_var_end(void);

+/* check needed privileges to perform SET PERSIST[_only] or RESET PERSIST */
+bool check_priv(THD *thd, bool static_variable);
+
